import test from 'node:test';import assert from 'node:assert/strict';import {Element} from './helpers/panel-dom.js';import {savedRehearsalGuideFixtures,until} from './helpers/workspace-fixtures.js';import {sampleHistory} from './helpers/report-history-fixtures.js';import {prepareReportHistoryFile} from '../src/report-history-file.js';
import {prepareWalletSavedSourceBundle,reviewWalletSavedBundle,encodeWalletSavedBundleReview} from '../src/file-read-status.js';import {mountSavedComparisonBundlePanel} from '../examples/file-read-panel.js';
test('owned successful and mismatching bundle receipts omit addresses, source bodies and private notes',async()=>{
 const history=structuredClone(sampleHistory());history.entries[0].note='PRIVATE_NOTE_MARKER';const original=(await prepareReportHistoryFile(history)).text,plain=savedRehearsalGuideFixtures()[0].text;
 for(const text of[original,plain]){const prepared=await prepareWalletSavedSourceBundle(text,text),receipt=await reviewWalletSavedBundle(prepared.text),saved=encodeWalletSavedBundleReview(receipt);assert.equal(saved,JSON.stringify(receipt,null,2)+'\n');assert.doesNotMatch(saved,/PRIVATE_NOTE_MARKER|0x[0-9a-f]{40}|beforeFileText|afterFileText/);assert.equal(JSON.parse(saved).containsOriginalEvidence,false);assert.throws(()=>encodeWalletSavedBundleReview(JSON.parse(saved)),{code:'FILE_BUNDLE_REVIEW_RESULT'});
  const altered=JSON.parse(prepared.text),comparison=JSON.parse(altered.comparisonText);comparison.authenticated=true;altered.comparisonText=JSON.stringify(comparison);const mismatch=await reviewWalletSavedBundle(JSON.stringify(altered));assert.equal(JSON.parse(encodeWalletSavedBundleReview(mismatch)).comparisonMatchesRecomputation,false);
 }
});
async function setup(){const parent=new Element('div'),document={createElement:tag=>new Element(tag)},downloads=[];let callback=()=>{};const panel=mountSavedComparisonBundlePanel({document,parent,download:value=>{downloads.push(value);callback();}}),q=name=>parent.find('saved-bundle-'+name),text=savedRehearsalGuideFixtures()[0].text,prepared=await prepareWalletSavedSourceBundle(text,text);const load=async value=>{q('file').files=[new File([value],'bundle.json')];q('file').dispatchEvent(new Event('change'));await until(()=>!panel.getState().busy);};await load(prepared.text);return{panel,q,downloads,load,bundle:prepared.text,callback:value=>{callback=value;}};}
test('receipt-only save uses a separate acknowledgement and works for a mismatch with extraction disabled',async()=>{
 const f=await setup();try{f.q('source-ack').checked=true;f.q('source-ack').dispatchEvent(new Event('change'));assert(f.q('review-save').disabled);f.q('review-ack').checked=true;f.q('review-ack').dispatchEvent(new Event('change'));f.q('review-save').click();assert.equal(f.downloads.length,1);assert.equal(f.downloads[0].containsOriginalEvidence,false);assert.doesNotMatch(f.downloads[0].text,/0x[0-9a-f]{40}/);assert(f.q('review-save').disabled);
  const altered=JSON.parse(f.bundle),comparison=JSON.parse(altered.comparisonText);comparison.sourceTextComparison.sameText=false;altered.comparisonText=JSON.stringify(comparison);await f.load(JSON.stringify(altered));assert(f.q('before').disabled);assert(!f.q('review-ack').disabled);f.q('review-ack').checked=true;f.q('review-ack').dispatchEvent(new Event('change'));f.q('review-save').click();assert.equal(JSON.parse(f.downloads.at(-1).text).comparisonMatchesRecomputation,false);await f.load('{}');assert(f.q('review-save').disabled);assert.equal(f.panel.getState().receipt,null);
 }finally{f.panel.dispose();}
});
test('receipt delivery cannot overwrite a replacement review or execute after disposal',async()=>{
 const f=await setup();let pending;try{f.callback(()=>{pending=f.load('{}');});f.q('review-ack').checked=true;f.q('review-ack').dispatchEvent(new Event('change'));f.q('review-save').click();await pending;assert.doesNotMatch(f.q('status').textContent,/保存処理を開始しました/);const button=f.q('review-save'),count=f.downloads.length;f.panel.dispose();button.click();assert.equal(f.downloads.length,count);}finally{f.panel.dispose();}
});
